def test_blueprint_registration_name_collision(app):
    first = flask.Blueprint("same", __name__)
    second = flask.Blueprint("same", __name__)
    app.register_blueprint(first)
    app.register_blueprint(second, name="other")

    assert app.blueprints == {"same": first, "other": second}

    with pytest.raises(AssertionError):
        app.register_blueprint(first, name="other")


